math_server = FastMCP("Math")

@math_server.tool()
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b

@math_server.tool()
def subtract(a: float, b: float) -> float:
    """Subtract b from a."""
    return a - b

@math_server.tool()
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
