        raise ValueError("Cannot divide by zero")
    return a / b

# Create the main server
main_server = FastMCP("Calculator")

# Attach the math sub-server under the "math" namespace
main_server.add_provider(math_server, namespace="math")

# Add some tools directly to the main server
